fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn h(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn r(s:&str)->String{format!("{R}/{s}")}
fn eq(x:f64,y:f64){assert!((x-y).abs()<=1e-12*x.abs().max(y.abs()).max(1.));}fn med(v:&[f64])->f64{let mut v=v.to_vec();v.sort_by(f64::total_cmp);v[v.len()/2]}fn stats(v:&[f64],a:&Value){assert_eq!(v.len(),15);let mut v2=v.to_vec();v2.sort_by(f64::total_cmp);eq(v2[3],a["low"].as_f64().unwrap());eq(v2[7],a["median"].as_f64().unwrap());eq(v2[11],a["high"].as_f64().unwrap());assert_eq!(v.iter().filter(|&&x|x<1.).count(),a["wins"].as_u64().unwrap()as usize);for(i,x)in v.iter().enumerate(){eq(*x,a["ratios"][i].as_f64().unwrap());}}
fn main(){assert!(!Path::new(&r("review.json")).exists());let audit=read(r("source-audit.json"));let m=read(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let originals=m["source_files_sha256"].as_object().unwrap();assert_eq!(originals.len(),176);let mut recovered=0;let mut unchanged=0;
for(p,sha)in originals{assert_eq!(h(format!("{Z}/{p}")),sha.as_str().unwrap());let bytes=fs::read(r(&format!("source/{p}"))).unwrap();if h(r(&format!("source/{p}")))==sha.as_str().unwrap(){unchanged+=1;}let restored=if let Some(s)=audit["suffixes"].get(p){bytes.strip_suffix(s.as_str().unwrap().as_bytes()).unwrap()}else{&bytes};assert_eq!(format!("{:x}",Sha256::digest(restored)),sha.as_str().unwrap());recovered+=1;}assert_eq!(unchanged,172);assert_eq!(recovered,176);
let clone=&audit["apply_clone"];let body=fs::read_to_string(r("native-apply.rs")).unwrap();assert_eq!(body,clone["candidate"]);assert!(fs::read_to_string(r("source/crates/zopro-core/src/msm/native_buckets.rs")).unwrap().contains(&body));let mut restored=body;for change in clone["edits"].as_array().unwrap().iter().rev(){let from=change[1].as_str().unwrap();assert_eq!(restored.matches(from).count(),1);restored=restored.replacen(from,change[0].as_str().unwrap(),1);}assert_eq!(restored,clone["original"]);assert!(fs::read_to_string(format!("{Z}/crates/zopro-core/src/msm/g2_borrowed.rs")).unwrap().contains(&restored));assert_eq!(h(r("source/crates/zopro-bn254/src/native_bucket_store.rs")),audit["store_sha256"]);assert_eq!(h(audit["store_original"].as_str().unwrap()),audit["store_sha256"]);
let mut native_commands=0;for s in read(r("build-plan.json"))["steps"].as_array().unwrap(){let base=r(&format!("native/{}",s["name"].as_str().unwrap()));let e=read(format!("{base}/exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for f in["stdout","stderr"]{assert_eq!(h(format!("{base}/{f}.log")),e[format!("{f}_sha256")]);}let c=read(format!("{base}/command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],s["argv"].as_array().unwrap());let mut env=s.get("environment").cloned().unwrap_or(json!({}));env.as_object_mut().unwrap().remove("RUSTC");assert_eq!(c["environment"],env);native_commands+=1;}assert_eq!(native_commands,7);
let store=fs::read_to_string(r("native/store-tests/stdout.log")).unwrap();assert!(store.contains("2 passed; 0 failed; 0 ignored; 0 measured; 35 filtered out"));
for label in["control","candidate"]{let log=fs::read_to_string(r(&format!("native/{label}-build/stderr.log"))).unwrap();let line=log.lines().find(|l|l.contains("Running")&&l.contains("--crate-name zopro_native_buckets")).unwrap();for f in["-C opt-level=3","-C lto -C","-C codegen-units=1","-C target-cpu=native"]{assert!(line.contains(f));}assert_eq!(line.contains("--cfg zopro_native_buckets"),label=="candidate");}assert!(fs::read_to_string(r("driver/Cargo.toml")).unwrap().contains("lto=true"));
let buildpins=read(r("build-pins.json"));for(p,v)in buildpins.as_object().unwrap(){assert_eq!(h(p),v.as_str().unwrap());}
let core=fs::read_to_string(r("native/core-tests/stdout.log")).unwrap();assert!(core.contains("test result: ok. 128 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));let pins=read(r("pins.json"));for(p,sha)in pins.as_object().unwrap(){assert_eq!(h(p),sha.as_str().unwrap());}let plan=read(r("plan.json"));assert_eq!(plan["steps"].as_array().unwrap().len(),475);let a=read(r("analysis.json"));let mut timed=BTreeMap::<(String,String,usize),Value>::new();let mut profiles=BTreeMap::new();let mut callers=0;
for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let base=r(&format!("runs/{name}"));let exit=read(format!("{base}/exit.json"));assert_eq!(exit["returncode"],0);assert_eq!(exit["success"],true);for stream in["stdout","stderr"]{assert_eq!(h(format!("{base}/{stream}.log")),exit[format!("{stream}_sha256")]);}let cmd=read(format!("{base}/command.json"));assert_eq!(cmd["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap()[..]);assert_eq!(cmd["environment"],step["environment"]);if name!="preflight-check"&&["preflight-","latency-","stat-","cycles-"].iter().any(|s|name.starts_with(s)){let text=fs::read_to_string(format!("{base}/stdout.log")).unwrap();let rows=text.lines().filter_map(|l|l.strip_prefix("CALLER ")).collect::<Vec<_>>();assert_eq!(rows.len(),1);let value:Value=serde_json::from_str(rows[0]).unwrap();assert_eq!(value,a["caller_receipts"][name]);assert_eq!(value["timed_allocations"],0);assert_eq!(value["complete_generator_oracle"],true);let workers=value["workers"].as_u64().unwrap();let mut indices=BTreeSet::new();let mut tids=BTreeSet::new();for worker in value["worker_rows"].as_array().unwrap(){let i=worker["worker"].as_u64().unwrap();assert!(i<workers);assert_eq!(worker["cpu"],if workers==1{2}else{i});assert!(indices.insert(i));assert!(tids.insert(worker["tid"].as_u64().unwrap()));}assert_eq!(indices.len(),workers as usize);if name.starts_with("latency-"){let fields=name.rsplitn(3,'-').collect::<Vec<_>>();let arm=fields[0];let block=fields[1].trim_start_matches('b').parse::<usize>().unwrap();let context=name.strip_prefix("latency-").unwrap().rsplitn(3,'-').last().unwrap();assert!(timed.insert((context.into(),arm.into(),block),value.clone()).is_none());}if name.starts_with("cycles-"){profiles.insert(name.to_owned(),value);}callers+=1;}}
assert_eq!(callers,444);assert_eq!(timed.len(),405);let mut failed=vec![];let mut ratios=BTreeMap::new();for row in a["rows"].as_array().unwrap(){let context=row["context"].as_str().unwrap();let mut times=BTreeMap::new();for arm in["frozen","OFF","ON"]{let mut t=vec![];let mut cpu=vec![];let mut maxrss=0f64;for b in 0..15{let raw=&timed[&(context.into(),arm.into(),b)];assert_eq!(raw["rounds_per_worker"],4096);for other in["frozen","OFF","ON"]{let q=&timed[&(context.into(),other.into(),b)];assert_eq!(raw["output_sha256"],q["output_sha256"]);assert_eq!(raw["scratch_capacity_bytes_by_worker"],q["scratch_capacity_bytes_by_worker"]);}t.push(raw["elapsed_ns"].as_f64().unwrap()/4096.);cpu.push((raw["usage"]["user_cpu_ms"].as_f64().unwrap()+raw["usage"]["system_cpu_ms"].as_f64().unwrap())/4096.);maxrss=maxrss.max(raw["usage"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.);assert_eq!(raw["scratch_capacity_bytes_by_worker"][0],row["scratch_capacity_bytes_first_worker"][arm]);}eq(med(&t),row["median_ns_per_wave"][arm].as_f64().unwrap());eq(med(&cpu),row["CPU_ms_per_wave"][arm].as_f64().unwrap());eq(maxrss,row["counter_RSS_MiB_diagnostic"][arm].as_f64().unwrap());times.insert(arm,t);}
for(n,d)in[("OFF","frozen"),("ON","frozen"),("ON","OFF")]{let v=times[n].iter().zip(&times[d]).map(|(n,d)|n/d).collect::<Vec<_>>();let report=&row["pairs"][format!("{n}/{d}")];stats(&v,report);let pass=if n=="OFF"||(context.starts_with("G1-")&&d=="OFF"){report["low"].as_f64().unwrap()>=1./1.03&&report["high"].as_f64().unwrap()<=1.03}else{report["high"].as_f64().unwrap()<=1.03};if !pass{failed.push(format!("{context}/{n}/{d}/{}",if n=="OFF"{"calibration"}else{"nonregression"}));}if context.starts_with("G2-")&&context.ends_with("-w32")&&n=="ON"&&(report["high"].as_f64().unwrap()>=1.||report["wins"].as_u64().unwrap()<10){failed.push(format!("{context}/ON/{d}/gain"));}ratios.insert(format!("{context}/{n}/{d}"),v);}}
for control in["frozen","OFF"]{let v=(0..15).map(|i|((ratios[&format!("G2-200-w32/ON/{control}")][i].ln()+ratios[&format!("G2-352-w32/ON/{control}")][i].ln())/2.).exp()).collect::<Vec<_>>();let stats_v=&a["G2_32_aggregates"][control];stats(&v,stats_v);if stats_v["high"].as_f64().unwrap()>=1.||stats_v["wins"].as_u64().unwrap()<10{failed.push(format!("G2-32aggregate/ON/{control}/gain"));}}
let symbols=read(r("profile-symbols.json"));let mut total_samples=0;for(name,raw)in profiles{let pid=raw["pid"].as_u64().unwrap();let mut bins=BTreeMap::<String,u64>::new();let mut count=0;let mut unknown=0;for l in fs::read_to_string(r(&format!("runs/decode-{name}/stdout.log"))).unwrap().lines().filter(|l|!l.starts_with('#')&&!l.trim().is_empty()){let f=l.split_whitespace().collect::<Vec<_>>();let(p,t)=f[0].split_once('/').unwrap();assert_eq!(p.parse::<u64>().unwrap(),pid);let tid=t.parse::<u64>().unwrap();assert!(tid==pid||raw["worker_rows"].as_array().unwrap().iter().any(|x|x["tid"]==tid));assert!(f[1].trim_matches(['[',']']).parse::<u64>().unwrap()<32);assert_eq!(f[3].parse::<u64>().unwrap(),16000000);let symbol=f[5..].join(" ");let symbol=rustc_demangle::try_demangle(&symbol).map(|s|format!("{s:#}")).unwrap_or(symbol);if symbol.starts_with("[unknown]"){unknown+=1;}*bins.entry(symbol).or_default()+=1;count+=1;}assert_eq!(json!(bins),symbols[&name]);let share=unknown as f64/count as f64;eq(share,a["profiles"][&name]["unknown_share"].as_f64().unwrap());assert_eq!(a["profiles"][&name]["samples"],count);assert_eq!(read(r(&format!("runs/loss-{name}/stdout.log")))["zero_lost"],true);if count<1000||share>0.05{failed.push(format!("{name}/profile"));}let own=read(r(&format!("runs/own-{name}/stdout.log")));assert_eq!(own["sha256_before"],own["sha256_after"]);assert_eq!(h(r(&format!("perf/{name}.data"))),own["sha256_after"]);let stat=name.replacen("cycles-","stat-",1);let mut events=0;for l in fs::read_to_string(r(&format!("stat/{stat}.csv"))).unwrap().lines().filter(|l|!l.starts_with('#')&&!l.trim().is_empty()){let f=l.split(';').collect::<Vec<_>>();let event=f[2].trim();if !["cycles:u","instructions:u","cache-misses:u","branch-misses:u"].contains(&event){continue;}assert!(f[4].trim().parse::<f64>().unwrap()>=99.9);let n=f[0].trim().parse::<f64>().unwrap();eq(n,a["counters"][&stat][event]["count"].as_f64().unwrap());eq(n/16384.,a["counters"][&stat][event]["per_wave"].as_f64().unwrap());events+=1;}assert_eq!(events,4);total_samples+=count;}
failed.sort();let mut reported=serde_json::from_value::<Vec<String>>(a["failed_checks"].clone()).unwrap();reported.sort();assert_eq!(failed,reported);assert_eq!(a["gate_passed"],failed.is_empty());fs::write(r("review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"command_receipts":482,"capture_commands":475,"native_commands":7,"callers":444,"private_source_files":178,"original_source_files_recovered":recovered,"original_source_files_unchanged":172,"native_core_tests":128,"original_field_arithmetic_unchanged":true,"old_store_byte_exact":true,"focused_store_tests_passed":2,"original_field_tests_inherited":35,"original_point_finishing_and_scalar_tail_recovered_exact":true,"raw_latency_CPU_counter_memory_statistics_recomputed":true,"all_capacities_equal_and_zero_timed_allocations":true,"all_profile_symbol_bins_and_PIDs_TIDs_CPU_period_checked":true,"samples":total_samples,"gate_passed":failed.is_empty(),"failed_checks":failed,"new_proofs":0,"proof_ledger":30846,"adopted":false})).unwrap()).unwrap();println!("Independent review PASS:482commands/444callers/{total_samples}samples;gate={}",failed.is_empty());}
